const BUILDER_BY_ID = Object.freeze(Object.fromEntries(BUILDER_CATALOG.map(entry => [entry.id, entry])));
const BUILDER_GROUPS = Object.freeze([...new Set(BUILDER_CATALOG.map(entry => entry.group))]);
const BUILDER_COUNT = BUILDER_CATALOG.length;

if (BUILDER_COUNT !== 100) throw new Error(`Builder catalog must contain 100 ideas; found ${BUILDER_COUNT}`);

// HTTP and the desktop sneakers:// protocol can fetch the JSON manifest. A
// browser opened directly on editor.html with file:// cannot, so keep the
// exact same generated manifest available as a local module fallback.
function lowMemoryDevice() {
  const memory = Number(globalThis.navigator?.deviceMemory || 0);
  const connection = globalThis.navigator?.connection;
  const narrow = typeof globalThis.matchMedia === 'function' && matchMedia('(max-width: 700px)').matches;
  return (memory > 0 && memory <= 2) || connection?.saveData === true || narrow;
}

function compactSprites(sprites) {
  return Object.fromEntries(Object.entries(sprites).map(([name, frames]) => [name, frames.map(frame => ({
    ...frame,
    // Only texture coordinates shrink. World dimensions and ground pivots
    // must still match the same collision geometry on every device.
    rect: frame.rect.map(value => Math.round(value / 2)),
  }))]));
}

function chooseManifest(data) {
  const lowMemory = lowMemoryDevice();
  // The growing desktop atlas exceeded 73 million decoded pixels. Sampling
  // it repeatedly stalls canvas even on a fast desktop. Use the already
  // authored 1x delivery texture when the 2x sheet exceeds our texture budget;
  // canvas resolution and all world-space dimensions remain unchanged.
  const oversized = data.size[0] > 8192 || data.size[1] > 8192 || data.size[0] * data.size[1] > 24_000_000;
  const compact = (lowMemory || oversized) && data.lowMemory;
  if (!compact) return {...data, lowMemoryActive: lowMemory, compactAtlasActive: false};
  return {...data, ...compact, sprites: compactSprites(data.sprites), lowMemoryActive: lowMemory, compactAtlasActive: true};
}

async function loadRuntimeManifest() {
  if (typeof location !== 'undefined' && location.protocol === 'file:') {
    if (globalThis.__SNEAKERS_RUNTIME_MANIFEST__) return chooseManifest(globalThis.__SNEAKERS_RUNTIME_MANIFEST__);
    const module = await import('./runtime-manifest.js?v=7');
    return chooseManifest(module.RUNTIME_MANIFEST);
  }
  // The JSON itself is also revalidated so a CDN cannot serve a new HTML
  // shell with an older atlas manifest.
  const response = await fetch('assets/runtime/sprites.json', { cache: 'default' });
  if (!response.ok) throw new Error('The artwork could not be loaded.');
  return chooseManifest(await response.json());
}

// Depth is presentation-only. These tracks never participate in collision or
// route timing; they only decide where transparent dressing is painted.
const BACKGROUND_PARALLAX = 2.1;
const BACKGROUND_ALPHA = .72;
const BACKGROUND_FOCAL_X = 400;
// Reserve the whole standing runner silhouette plus breathing room. This is
// a presentation boundary, never a collision surface or change to physics.
const BACKGROUND_LANE_CLEARANCE = 168;

// Cover the canvas while registering the runner to the plate's foreground.
// A portrait crop makes the painted roadway taller on screen; keep dressing
// behind its authored rear edge as well as above the runner's silhouette.
function backgroundPlateFor(width, height, ground, imageRatio, scale, sceneProfile) {
  const floor = .86;
  const plateHeight = Math.max(width / imageRatio, ground / floor, (height - ground) / (1 - floor));
  const top = ground - plateHeight * floor;
  const rearEdge = top + plateHeight * (sceneProfile?.dressingLine ?? sceneProfile?.foregroundBand?.[0] ?? .67);
  const laneClearance = Math.max(BACKGROUND_LANE_CLEARANCE, (ground - rearEdge) / scale);
  return { width: plateHeight * imageRatio, height: plateHeight, top, laneClearance };
}

const BACKGROUND_TRACKS = Object.freeze({
  1: Object.freeze({ speed: 1.5, scale: .5, lift: 168 }),
  2: Object.freeze({ speed: 2, scale: .65, lift: 168 }),
  3: Object.freeze({ speed: 3, scale: .8, lift: 168 }),
});

function backgroundTrackFor(entity, shape) {
  if (entity.backgroundTrack && BACKGROUND_TRACKS[entity.backgroundTrack]) return entity.backgroundTrack;
  const size = Math.max(shape?.width || 0, shape?.height || 0);
  return size < 160 ? 1 : size < 280 ? 2 : 3;
}

function backgroundLiftFor(entity, shape, track) {
  return Math.max(entity.backgroundLift || 0, BACKGROUND_TRACKS[track].lift - (entity.y || 0));
}

function backgroundPlacementFor(entity, shape, frame, worldHeight = Infinity, laneClearance = BACKGROUND_LANE_CLEARANCE) {
  const track = backgroundTrackFor(entity, shape), profile = BACKGROUND_TRACKS[track];
  const baseline = Math.max(BACKGROUND_LANE_CLEARANCE, laneClearance, (entity.y || 0) + backgroundLiftFor(entity, shape, track));
  const height = frame?.height || shape.height;
  const factor = Math.min(profile.scale, Math.max(1, worldHeight - baseline - 12) / height);
  // Registration room can extend below a frame's pivot. Place the complete
  // painted rectangle above the lane, then fit tall landmarks below the top.
  return { track, factor, elevation: baseline + (height - (frame?.pivotY ?? height)) * factor };
}

// Faster background motion is intentional. Anchor it to the authored encounter
// ahead of the runner, so a landmark crosses the focal point when its world
// position reaches that point instead of drifting away over a long chapter.
function backgroundScreenX(value, world, scale, track) {
  return (BACKGROUND_FOCAL_X + (value - world - BACKGROUND_FOCAL_X) * BACKGROUND_TRACKS[track].speed) * scale;
}






